// ==========================================================================
// ⚙️ CONFIGURAÇÃO GLOBAL DE TESTE & TRAVAS DE SEGURANÇA
// ==========================================================================
return [{
  json: {
    MODO_TESTE: 'ATIVO (100% SEGURO)',
    EMAIL_TESTE: 'gabriel.brittes@gritsch.com.br',
    FILIAL_TESTE: 'GRITSCH - GOI',
    DIAS_HISTORICO: 14,
    PREFIXO_ASSUNTO: '[TESTE DE LAYOUT] '
  }
}];

var config = $('00_Config_Teste').first().json;
var dias = config.DIAS_HISTORICO || 14;

var agora = new Date();
var fim = new Date(agora);
var inicio = new Date(agora);
inicio.setDate(agora.getDate() - dias);

var fmt = function(d) {
  return String(d.getDate()).padStart(2, '0') + '/' +
    String(d.getMonth() + 1).padStart(2, '0') + '/' +
    d.getFullYear();
};
var fmtPG = function(d) {
  return d.getFullYear() + '-' +
    String(d.getMonth() + 1).padStart(2, '0') + '-' +
    String(d.getDate()).padStart(2, '0');
};

return [{
  json: {
    dataRef: fmt(inicio) + ' a ' + fmt(fim),
    semanaInicio: fmtPG(inicio),
    semanaFim: fmtPG(fim),
    emailDestinoTeste: config.EMAIL_TESTE || 'gabriel.brittes@gritsch.com.br',
    filialTeste: config.FILIAL_TESTE || 'GRITSCH - GOI',
    prefixoAssunto: config.PREFIXO_ASSUNTO || '[TESTE] '
  }
}];

var items = $input.all();
var periodo = $('01 - Calcular Periodo das Datas').first().json;
var dataRef = periodo.dataRef;
var emailTeste = periodo.emailDestinoTeste || 'gabriel.brittes@gritsch.com.br';

if (items.length === 0 || !items[0].json.placa) {
  return [{ json: { _semEventos: true, dataRef: dataRef, emailDestino: emailTeste } }];
}

var grouped = {};
for (var i = 0; i < items.length; i++) {
  var d = items[i].json;
  var filial = d.filial_operacional || 'DESCONHECIDA';
  if (!grouped[filial]) grouped[filial] = [];
  grouped[filial].push(d);
}

var results = [];
var filiais = Object.keys(grouped);
for (var fi = 0; fi < filiais.length; fi++) {
  var filial = filiais[fi];
  var evs = grouped[filial];
  var total = evs.length;
  var vels = evs.map(function(e) { return parseFloat(e.velocidade_registrada) || 0; });
  var velMax = Math.max.apply(null, vels);
  var velMedia = Math.round((vels.reduce(function(s,v){return s+v;},0) / vels.length) * 10) / 10;

  var porPlaca = {};
  for (var ei = 0; ei < evs.length; ei++) {
    var e = evs[ei];
    if (!porPlaca[e.placa]) {
      porPlaca[e.placa] = {
        placa: e.placa,
        modelo: e.modelo || '--',
        grupo_veiculo: e.grupo_veiculo || 'Leve',
        provedor: e.provedor_rastreador || 'NUXEO',
        qtd: 0,
        velMax: 0,
        somaVel: 0
      };
    }
    porPlaca[e.placa].qtd++;
    var v = parseFloat(e.velocidade_registrada) || 0;
    porPlaca[e.placa].somaVel += v;
    if (v > porPlaca[e.placa].velMax) porPlaca[e.placa].velMax = v;
  }

  var tabelaPlacas = Object.keys(porPlaca).map(function(p) {
    var item = porPlaca[p];
    item.velMedia = Math.round((item.somaVel / item.qtd) * 10) / 10;
    return item;
  }).sort(function(a,b){ return b.qtd - a.qtd; });

  var topOc = evs.slice().sort(function(a,b){
    return (parseFloat(b.velocidade_registrada)||0) - (parseFloat(a.velocidade_registrada)||0);
  }).slice(0, 8).map(function(e){
    return {
      placa: e.placa,
      modelo: e.modelo || '--',
      velocidade: parseFloat(e.velocidade_registrada) || 0,
      data: e.data_hora_alerta,
      local: (e.cidade || '') + (e.estado ? '/' + e.estado : ''),
      origem: e.provedor_rastreador || 'NUXEO'
    };
  });

  var porDia = {};
  for (var ei2 = 0; ei2 < evs.length; ei2++) {
    var dt = evs[ei2].data_ref ? String(evs[ei2].data_ref).substring(0,10) : 'desconhecido';
    if (!porDia[dt]) porDia[dt] = { qtd: 0, max: 0 };
    porDia[dt].qtd++;
    var vd = parseFloat(evs[ei2].velocidade_registrada) || 0;
    if (vd > porDia[dt].max) porDia[dt].max = vd;
  }
  var breakdownDias = Object.keys(porDia).sort().map(function(dia){
    return { dia: dia, qtd: porDia[dia].qtd, velPico: porDia[dia].max };
  });

  var ccParts = [];
  if (evs[0].email_cc_original_filial) ccParts.push(evs[0].email_cc_original_filial);
  if (evs[0].cc_regional_original_filial) ccParts.push(evs[0].cc_regional_original_filial);
  if (evs[0].cc_global_original) ccParts.push(evs[0].cc_global_original);
  var emailCCOriginalFinal = ccParts.join(';').split(/[;,]+/).map(function(s){return s.trim();}).filter(Boolean).filter(function(v,i,a){return a.indexOf(v)===i;}).join(',');

  results.push({ json: {
    filial: filial,
    dataRef: dataRef,
    totalEventos: total,
    qtdVeiculos: tabelaPlacas.length,
    velMax: velMax,
    velMedia: velMedia,
    tabelaPlacas: tabelaPlacas,
    topOcorrencias: topOc,
    breakdownDias: breakdownDias,
    emailDestinoOriginal: evs[0].email_destino_original_filial,
    emailCCOriginal: emailCCOriginalFinal,
    emailDestino: emailTeste,
    consolidadoDestinatariosOriginal: evs[0].consolidado_destinatarios_db,
    consolidadoCCOriginal: evs[0].consolidado_cc_db
  }});
}

return results;

var filiais = $input.all();
var config = $('00_Config_Teste').first().json;
var filialAlvo = config.FILIAL_TESTE || 'GRITSCH - GOI';

var selecionada = filiais.find(function(f) { return f.json.filial === filialAlvo; }) || filiais[0];
return [selecionada];

var filiais = $('03 - Agrupar Estatisticas por Filial').all();
var periodo = $('01 - Calcular Periodo das Datas').first().json;
var emailTeste = periodo.emailDestinoTeste || 'gabriel.brittes@gritsch.com.br';

var totalEventosGeral = 0, velMaxGeral = 0, somaVel = 0, countVel = 0;
var rankingFiliais = [];
var todosVeiculos = [];

for (var i = 0; i < filiais.length; i++) {
  var f = filiais[i].json;
  totalEventosGeral += f.totalEventos;
  if (f.velMax > velMaxGeral) velMaxGeral = f.velMax;
  somaVel += f.velMedia * f.totalEventos;
  countVel += f.totalEventos;

  rankingFiliais.push({
    filial: f.filial,
    regional: f.emailCCOriginal || 'Diretoria',
    totalEventos: f.totalEventos,
    qtdVeiculos: f.qtdVeiculos,
    velMax: f.velMax,
    velMedia: f.velMedia
  });

  var tp = f.tabelaPlacas || [];
  for (var j = 0; j < tp.length; j++) {
    todosVeiculos.push(Object.assign({}, tp[j], { filial: f.filial }));
  }
}

rankingFiliais.sort(function(a,b){ return b.totalEventos - a.totalEventos; });
todosVeiculos.sort(function(a,b){ return b.qtd - a.qtd; });

var velMediaGeral = countVel > 0 ? Math.round((somaVel / countVel) * 10) / 10 : 0;

return [{
  json: {
    dataRef: periodo.dataRef,
    emailDestinoFinal: emailTeste,
    destinatariosConsolidadoReal: filiais[0] && filiais[0].json && filiais[0].json.consolidadoDestinatariosOriginal ? filiais[0].json.consolidadoDestinatariosOriginal : 'jefferson@gritsch.com.br',
    ccConsolidadoReal: filiais[0] && filiais[0].json && filiais[0].json.consolidadoCCOriginal ? filiais[0].json.consolidadoCCOriginal : 'sandro@gritsch.com.br,torredecontrole@gritsch.com.br,flavio@gritsch.com.br,fabio.pepplow@gritsch.com.br',
    totalEventosGeral: totalEventosGeral,
    totalFiliais: rankingFiliais.length,
    totalVeiculosGeral: todosVeiculos.length,
    velMaxGeral: velMaxGeral,
    velMediaGeral: velMediaGeral,
    rankingFiliais: rankingFiliais,
    topVeiculos: todosVeiculos.slice(0, 10)
  }
}];
